//! Important header keys. Port of `org.apache.camel.util.ImportantHeaderUtils`.

use std::collections::HashSet;
use std::sync::OnceLock;

/// All the important header keys.
///
/// The list between the markers is generated by the Camel build tooling from the component
/// catalog (headers marked as important) - do **not** edit it by hand.
pub const IMPORTANT_HEADER_KEYS: &[&str] = &[
    // Generated by camel build tools - do NOT edit this list!
    // IMPORTANT-HEADER-KEYS: START
    "CamelAggregatedCorrelationKey",
    "CamelAggregatedSize",
    "CamelAsteriskEventName",
    "CamelAtmosphereWebsocketEventType",
    "CamelExecExitValue",
    "CamelFileLength",
    "CamelFileName",
    "CamelFtpReplyCode",
    "CamelFtpReplyString",
    "CamelHttpResponseCode",
    "CamelHttpResponseText",
    "CamelKafkaKey",
    "CamelKafkaOffset",
    "CamelKafkaPartition",
    "CamelKafkaShareDeliveryCount",
    "CamelKafkaTopic",
    "CamelMqttTopic",
    "CamelNatsDeliveryCounter",
    "CamelNatsSID",
    "CamelNatsStatusCode",
    "CamelNatsStatusError",
    "CamelNettyRemoteAddress",
    "CamelRockerMQKey",
    "CamelSplitIndex",
    "CamelSplitSize",
    "CamelSqlRowCount",
    "CamelSqlStoredUpdateCount",
    "CamelSqlUpdateCount",
    "CamelSshExitValue",
    "Content-Type",
    "websocket.eventType",
    // IMPORTANT-HEADER-KEYS: END
];

/// All the important header keys as a set.
pub fn get_important_header_keys() -> &'static HashSet<&'static str> {
    static SET: OnceLock<HashSet<&'static str>> = OnceLock::new();
    SET.get_or_init(|| IMPORTANT_HEADER_KEYS.iter().copied().collect())
}

/// Whether the given header or exchange property is marked as important.
///
/// # Arguments
///
/// * `key` - the header key (case sensitive)
///
/// # Returns
///
/// `true` if important, `false` otherwise.
pub fn is_important_header(key: &str) -> bool {
    get_important_header_keys().contains(key)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn important() {
        assert!(is_important_header("CamelFileName"));
        assert!(is_important_header("Content-Type"));
        assert!(!is_important_header("camelfilename"));
        assert!(!is_important_header("foo"));
    }
}
